      throw new Error(`Richiesta annullata: ${url}`);

    }



    console.error(`Errore durante il recupero dei dati da ${url}:`, error);

    throw error;

  } else {

    throw new Error(`Errore non gestito durante il recupero dei dati da ${url}`);

  }

}

