          eventType: 'other', // Tipo generico per eventi importati

          clientId: 1, // Utente default o placeholder (deve esistere nel database)

          status: 'upcoming',

          googleCalendarEventId: googleEvent.id,

          googleCalendarSynced: true,

        });



